extension Cause {
    public var text: String {
        switch self {
        case .noSources: L.causeNoSources
        case .noConnection: L.causeNoConnection
        case .airsToday(let time): L.causeAirsToday(time: time)
        case .airsTomorrow(let time): L.causeAirsTomorrow(time: time)
        case .airsInDays(let days, let time): L.causeAirsInDays(days: Int(days), time: time)
        case .airsOnDate(let date, let time): L.causeAirsOnDate(date: date, time: time)
        case .noPlayableStream: L.causeNoPlayableStream
        case .titleNoMatch(let detail): L.causeTitleNoMatch(detail: detail)
        case .sourceGone(let source): L.causeSourceGone(source: source)
        case .releaseFailed(let detail): L.causeReleaseFailed(detail: detail)
        case .sourcesTimedOut: L.causeSourcesTimedOut
        case .noSourceHasEpisode(let episode, let detail): L.causeNoSourceHasEpisode(episode: episode, detail: detail)
        case .sourceCannotDownload: L.causeSourceCannotDownload
        case .noSourceCouldListShow: L.causeNoSourceCouldListShow
        case .subtitlesMerged(let tracks): L.causeSubtitlesMerged(tracks: Int(tracks))
        case .subtitlesLeftApart(let reason): L.causeSubtitlesLeftApart(reason: reason)
        case .alreadyInDownloads(let count): L.causeAlreadyInDownloads(count: Int(count))
        case .proxyNeedsAddress: L.causeProxyNeedsAddress
        case .proxyAddressUnusable: L.causeProxyAddressUnusable
        case .serverUnreachable: L.causeServerUnreachable
        case let .verbatim(text): text
        }
    }
}

private func spanText(_ s: KaeriKit.Span) -> String {
    let days = Int(s.days), hours = Int(s.hours), minutes = Int(s.minutes), seconds = Int(s.seconds)
    if days > 0 {
        return hours > 0 ? L.durationDaysHours(days: days, hours: hours) : L.durationDays(days: days)
    }
    if hours > 0 {
        return minutes > 0 ? L.durationHoursMinutes(hours: hours, minutes: minutes) : L.durationHours(hours: hours)
    }
    if minutes > 0 {
        return seconds > 0
            ? L.durationMinutesSeconds(minutes: minutes, seconds: String(format: "%02d", seconds))
            : L.durationMinutes(minutes: minutes)
    }
    return seconds > 0 ? L.durationSeconds(seconds: seconds) : L.durationMinutes(minutes: 0)
}

private func sizeText(_ s: Size) -> String {
    let number = s.value.formatted(.number.precision(.fractionLength(Int(s.decimals))))
    switch s.unit {
    case .byte: return L.sizeByte(value: number)
    case .kilobyte: return L.sizeKilobyte(value: number)
    case .megabyte: return L.sizeMegabyte(value: number)
    case .gigabyte: return L.sizeGigabyte(value: number)
    }
}
